import { FILOSOFIA } from "./linguagens";
import { extend, m, o, q, qe } from "./pack";

/* Filosofia, 2ª leva: questões diretas e no estilo ENEM (trecho de filósofo ou situação + pergunta). Chave "n". */

extend(FILOSOFIA, "Origem da filosofia", [
  q("A filosofia surgiu por volta do século VI a.C. em qual região?", ["Na Grécia Antiga, nas colônias jônicas", "No Egito, às margens férteis do Nilo", "Na China, com os discípulos de Confúcio", "Em Roma, entre os senadores da República"], 0, "Os primeiros filósofos viveram nas colônias gregas da Jônia (atual Turquia), como Mileto, onde viveu Tales."),
  q("Para Tales de Mileto, o princípio (arché) de todas as coisas era:", ["O fogo", "A água", "O ar", "Os números"], 1, "Tales via a água em tudo (vida, umidade, mudança de estado). O fogo é de Heráclito; o ar, de Anaxímenes; os números, de Pitágoras."),
  q("Heráclito afirmou que 'ninguém se banha duas vezes no mesmo rio'. A ideia central é:", ["Tudo está em constante mudança", "A água é o princípio de todas as coisas", "Nada muda de fato na natureza real", "Os rios são sagrados e não se tocam"], 0, "Para Heráclito, o real é fluxo: o rio e quem se banha já mudaram. O oposto foi defendido por Parmênides, para quem a mudança é ilusão."),
  q("Parmênides defendia que:", ["O ser não muda; mudar é ilusão", "Tudo flui sem parar, como um rio", "O átomo é o princípio de todas as coisas", "Os deuses criaram o mundo do nada"], 0, "Para Parmênides, 'o ser é, o não ser não é': o verdadeiro ser não muda; os sentidos que nos enganam."),
  q("Os pré-socráticos também são chamados de filósofos da physis porque:", ["Investigavam a natureza", "Eram todos médicos", "Estudavam a política", "Escreviam só poesia"], 0, "Physis = natureza. Eles buscavam o princípio que explica a natureza, sem recorrer aos mitos."),
  q("Demócrito defendia que tudo é formado por:", ["Quatro elementos misturados", "Átomos e vazio", "Ideias perfeitas", "Números e harmonias"], 1, "Para Demócrito (e Leucipo), a realidade é feita de átomos indivisíveis em movimento no vazio."),
  qe("“A admiração é o princípio da filosofia.” (Aristóteles)", "Segundo a frase, a filosofia começa com:", ["O espanto diante do mundo", "A obediência aos deuses", "O acúmulo de riqueza", "A guerra entre cidades"], 0, "Admirar (thaumazein) é espantar-se: ao estranhar o que parece óbvio, o ser humano começa a perguntar 'por quê?'."),
  qe("“Homero e Hesíodo atribuíram aos deuses tudo o que é vergonhoso entre os homens.” (Xenófanes)", "Xenófanes critica:", ["A filosofia racional dos jônios", "Os deuses humanizados dos mitos", "A democracia direta de Atenas", "Os números sagrados de Pitágoras"], 1, "Xenófanes critica os deuses dos poetas, que têm defeitos humanos. É um exemplo da passagem do mito ao logos."),
  qe("Situação: um professor pergunta 'o que é justiça?' e os alunos respondem com exemplos. Ele insiste: 'Mas o que todos esses exemplos têm em comum?'.", "A atitude do professor é tipicamente filosófica porque:", ["Busca o conceito comum aos casos", "Exige que os alunos decorem definições", "Rejeita qualquer exemplo dado em aula", "Quer encerrar logo a discussão da turma"], 0, "A filosofia busca o conceito universal (o que é a justiça em si), não só casos particulares, como fazia Sócrates."),
  qe("“O mito explica o mundo por narrativas sagradas; o logos, por argumentos que podem ser discutidos.”", "A diferença central apontada é que o logos:", ["Pode ser discutido pela razão", "Proíbe falar dos deuses e dos heróis", "É sempre escrito em versos e cantado", "Não tenta explicar a natureza do mundo"], 0, "O mito é aceito pela tradição e pela fé; o logos apresenta razões que podem ser examinadas, criticadas e corrigidas."),
  q("Pitágoras via a essência da realidade nos:", ["Átomos", "Números", "Mitos", "Sentidos"], 1, "Para os pitagóricos, o cosmos tem ordem matemática: harmonia musical, astros e formas seguem proporções numéricas."),
  m("Marque os pares pré-socrático → arché corretos:", ["Tales → água", "Anaxímenes → ar", "Heráclito → fogo", "Demócrito → água", "Pitágoras → ar"], [0, 1, 2], "Demócrito → átomos; Pitágoras → números."),
  m("Marque características do pensamento filosófico:", ["Busca de explicações racionais", "Questionamento do senso comum", "Argumentação que pode ser discutida", "Aceitação da tradição sem perguntas", "Explicação só por narrativas sagradas"], [0, 1, 2], "Aceitar tudo sem perguntar e explicar só por narrativas sagradas é próprio do mito."),
  o("Explique o que significou a 'passagem do mito ao logos' na Grécia Antiga.", "Foi a mudança na forma de explicar o mundo: em vez de narrativas sobre deuses, aceitas pela tradição, os primeiros filósofos buscaram explicações racionais para a natureza, baseadas em argumentos e observação, que podiam ser discutidas e criticadas.", [
    ["Mito explica por deuses e tradição", "deus", "mito", "narrativ", "tradic"],
    ["Logos busca explicação racional", "racional", "razao", "argument", "logos"],
    ["As explicações podem ser debatidas", "discut", "critic", "debat", "question"],
  ]),
], "n");

extend(FILOSOFIA, "Sócrates e Platão", [
  q("O método de Sócrates, de fazer perguntas até o interlocutor perceber suas contradições, chama-se:", ["Ironia e maiêutica", "Dúvida metódica cartesiana", "Experimentação empirista", "Dogmatismo da tradição"], 0, "Pela ironia, Sócrates mostrava que o outro não sabia o que achava saber; pela maiêutica, ajudava a 'dar à luz' ideias."),
  q("A frase 'Só sei que nada sei' expressa:", ["Consciência da própria ignorância", "Desprezo por todo tipo de conhecimento", "Certeza absoluta sobre todas as coisas", "Recusa total em pensar sobre a vida"], 1, "Saber que não sabe é o ponto de partida para buscar o conhecimento. Por isso Sócrates seria o mais sábio."),
  q("No Mito da Caverna, as sombras na parede representam:", ["As aparências do mundo sensível", "O mundo perfeito das ideias eternas", "A luz do Bem que guia a razão", "Os filósofos que saíram da caverna"], 1, "Os prisioneiros tomam as sombras pela realidade: é o mundo sensível, das aparências. A saída da caverna é o caminho até as ideias."),
  q("Para Platão, o conhecimento verdadeiro está no:", ["Mundo das ideias", "Mundo dos sentidos", "Corpo humano", "Costume da cidade"], 0, "As ideias (formas) são eternas e perfeitas; o mundo sensível é cópia imperfeita delas."),
  q("Sócrates foi condenado à morte em Atenas acusado de:", ["Corromper jovens e ofender deuses", "Roubar o tesouro do templo da cidade", "Trair Atenas em favor de Esparta", "Fugir da batalha contra os persas"], 1, "Em 399 a.C., foi acusado de impiedade e de corromper os jovens. Bebeu cicuta em vez de fugir."),
  q("Na República, Platão defende que a cidade ideal seja governada por:", ["Comerciantes", "Filósofos", "Soldados", "Sorteio entre todos"], 1, "O rei-filósofo, que conhece o Bem, governaria com justiça. Guardiões defendem e produtores sustentam a cidade."),
  qe("“Uma vida sem exame não vale a pena ser vivida.” (Sócrates, em Apologia)", "A frase defende que:", ["Devemos refletir sobre a vida", "As provas escolares não servem para nada", "Viver bem é apenas seguir os costumes", "Só os deuses podem julgar uma vida"], 0, "Examinar a vida é pensar sobre valores e escolhas. Para Sócrates, viver sem refletir é viver no automático."),
  qe("No Mito da Caverna, um prisioneiro é libertado, vê o sol e volta para contar aos outros. Eles riem e ameaçam matá-lo.", "A reação dos prisioneiros simboliza:", ["A resistência a verdades incômodas", "O sucesso imediato da filosofia na cidade", "O amor dos prisioneiros pela verdade", "A crença numa vida após a morte"], 0, "Quem vive de aparências resiste a quem traz uma verdade incômoda. Alusão à condenação de Sócrates."),
  qe("“Conhece-te a ti mesmo.” (inscrição no templo de Delfos, adotada por Sócrates)", "Para Sócrates, essa frase indica que a filosofia deve começar:", ["Pelo estudo dos astros", "Pelo autoconhecimento", "Pela leitura dos mitos", "Pela política da cidade"], 1, "Sócrates desloca a filosofia da natureza para o ser humano: conhecer a si mesmo é o primeiro passo para agir bem."),
  qe("Na alegoria platônica, a ideia de 'cadeira' é perfeita e única; as cadeiras que vemos são várias e imperfeitas.", "Segundo Platão, as cadeiras do dia a dia são:", ["Cópias imperfeitas da ideia", "Mais reais que a ideia de cadeira", "Ilusões sem relação com a ideia", "Criações diretas dos deuses do Olimpo"], 0, "Os objetos sensíveis 'participam' das ideias: são cópias que imitam um modelo perfeito."),
  q("Os sofistas eram criticados por Sócrates e Platão porque:", ["Cobravam para ensinar a vencer debates", "Não sabiam falar bem em público", "Recusavam qualquer participação política", "Viviam isolados no campo, longe de todos"], 0, "Os sofistas ensinavam retórica pagos, para convencer; Sócrates buscava a verdade, não a vitória no debate."),
  m("Marque ideias de Platão:", ["Mundo das ideias", "Mito da Caverna", "Rei-filósofo", "Tábula rasa", "Penso, logo existo"], [0, 1, 2], "Tábula rasa é de Locke; 'Penso, logo existo', de Descartes."),
  m("Marque o que caracteriza Sócrates:", ["Não deixou textos escritos", "Usava perguntas para examinar ideias", "Foi condenado à morte em Atenas", "Fundou a Academia", "Era sofista pago"], [0, 1, 2], "Quem fundou a Academia foi Platão; Sócrates não cobrava e criticava os sofistas."),
  o("Explique o Mito da Caverna de Platão e o que ele simboliza.", "Prisioneiros acorrentados numa caverna só veem sombras e acham que são a realidade. Um deles se liberta, sai, vê o sol e descobre o mundo verdadeiro. A caverna é o mundo sensível, das aparências; a saída é o caminho da filosofia até o mundo das ideias, e o sol representa o Bem.", [
    ["Prisioneiros veem sombras e as tomam como reais", "sombra", "prisioneir", "caverna"],
    ["A caverna = mundo sensível, das aparências", "sensivel", "aparencia", "sentidos"],
    ["Sair = conhecimento, mundo das ideias", "ideia", "conhecimento", "verdade", "sol", "filosof"],
  ]),
], "n");

extend(FILOSOFIA, "Aristóteles", [
  q("Diferente de Platão, Aristóteles defendia que o conhecimento começa:", ["Pelos sentidos e pela experiência", "Por ideias inatas vindas do céu", "Pela revelação dos deuses aos sábios", "Pelos sonhos e pelas visões noturnas"], 0, "Para Aristóteles, a essência está nas próprias coisas e é conhecida a partir dos sentidos, depois organizada pela razão."),
  q("Para Aristóteles, a finalidade última das ações humanas é:", ["A eudaimonia (felicidade)", "O acúmulo de riqueza material", "O poder sobre os outros cidadãos", "O prazer imediato do corpo"], 1, "A eudaimonia, uma vida plena segundo a virtude, é buscada por si mesma; o resto é meio para ela."),
  q("A teoria das quatro causas explica algo a partir de matéria, forma, agente e:", ["Finalidade", "Acaso cego", "Número exato", "Destino fixo"], 0, "Causas material, formal, eficiente e final. A estátua: mármore, forma de herói, escultor e o objetivo de homenagear."),
  q("Silogismo é:", ["Conclusão tirada de duas premissas", "Um tipo de poema épico grego antigo", "Uma lei da física de Aristóteles", "Uma forma de governo da pólis grega"], 0, "Ex.: 'Todo homem é mortal; Sócrates é homem; logo, Sócrates é mortal.' Aristóteles criou a lógica formal."),
  q("Aristóteles foi professor de:", ["Alexandre, o Grande", "Júlio César, o romano", "Platão, seu mestre", "Sócrates, o ateniense"], 1, "Aristóteles foi aluno de Platão e professor de Alexandre. Fundou sua própria escola, o Liceu."),
  q("Ato e potência, em Aristóteles, explicam:", ["A mudança dos seres", "A origem dos deuses", "A divisão de classes", "O movimento dos átomos"], 0, "A semente é árvore em potência; ao crescer, torna-se árvore em ato. Mudar é passar da potência ao ato."),
  qe("“O homem é por natureza um animal político.” (Aristóteles, Política)", "A afirmação significa que o ser humano:", ["Se realiza vivendo em comunidade", "Deve ser político de profissão", "Vive melhor isolado dos demais", "Nasce dominado só pelos instintos"], 0, "Fora da pólis, diz Aristóteles, o humano seria 'uma besta ou um deus': precisamos da vida em comum e da palavra."),
  qe("“A virtude é uma disposição de escolher o meio-termo, determinado pela razão.” (Ética a Nicômaco)", "Segundo o trecho, a generosidade estaria entre:", ["A avareza e o esbanjamento", "A coragem e a covardia diante do perigo", "A justiça e a obediência à lei", "O prazer e a dor do corpo humano"], 0, "A virtude fica entre dois vícios: a falta (avareza) e o excesso (esbanjamento). A coragem fica entre covardia e temeridade."),
  qe("“Somos o que repetidamente fazemos. A excelência, portanto, não é um ato, mas um hábito.” (frase atribuída à leitura de Aristóteles)", "A ideia central é que a virtude:", ["Se forma pela prática repetida", "Nasce pronta com cada pessoa", "Depende só da sorte de cada um", "É dada pelos deuses a poucos"], 1, "Para Aristóteles, tornamo-nos justos praticando atos justos: a virtude moral é adquirida pelo hábito."),
  qe("Silogismo: “Todo peixe vive na água. A baleia vive na água. Logo, a baleia é peixe.”", "Por que o raciocínio é inválido?", ["Viver na água não define peixe", "As duas premissas são totalmente falsas", "Faltam pelo menos três premissas a mais", "Baleias não vivem na água, e sim na terra"], 0, "A premissa diz que todo peixe vive na água, não que tudo que vive na água é peixe. A conclusão não decorre."),
  q("Para Aristóteles, a melhor forma de governo é aquela que:", ["Visa o bem comum", "Dá todo poder a um só", "Elimina as leis", "Serve aos mais ricos"], 0, "Monarquia, aristocracia e politeia (formas boas) visam o bem comum; tirania, oligarquia e demagogia, só o interesse de quem manda."),
  m("Marque ideias de Aristóteles:", ["Virtude como justo meio", "Animal político", "Quatro causas", "Mundo das ideias separado", "Tábula rasa"], [0, 1, 2], "Mundo das ideias é Platão; tábula rasa, Locke."),
  m("Marque os pares virtude → vícios (falta / excesso) corretos:", ["Coragem: covardia / temeridade", "Generosidade: avareza / esbanjamento", "Moderação: insensibilidade / intemperança", "Justiça: coragem / medo", "Prudência: riqueza / pobreza"], [0, 1, 2], "As duas últimas não são pares de vícios por falta e excesso."),
  o("Explique a ideia de virtude como 'justo meio' em Aristóteles, com um exemplo.", "Para Aristóteles, a virtude é o meio-termo entre dois vícios: um por falta e outro por excesso. A coragem, por exemplo, fica entre a covardia (falta) e a temeridade (excesso). O justo meio é definido pela razão prática (prudência) e se adquire pelo hábito.", [
    ["Meio-termo entre dois vícios", "meio", "vicio", "extremo"],
    ["Falta e excesso", "falta", "excesso"],
    ["Exemplo correto", "coragem", "covardia", "temeridade", "generos", "avareza"],
  ]),
], "n");

extend(FILOSOFIA, "Filosofia helenística", [
  q("Para os estoicos, a felicidade está em:", ["Viver pela razão e aceitar o inevitável", "Acumular o maior número de prazeres", "Fugir da cidade e viver isolado no campo", "Obedecer sempre às ordens do imperador"], 0, "O estoico distingue o que controla (juízos, escolhas) do que não controla (morte, fortuna) e busca a serenidade (apatheia)."),
  q("Epicuro defendia que o prazer verdadeiro é:", ["Ausência de dor e de perturbação", "Banquetes e festas sem fim nem limite", "Ter poder e influência sobre os outros", "Acumular riqueza material e bens de luxo"], 0, "Ataraxia (tranquilidade da alma) e aponia (ausência de dor). O prazer epicurista é moderado, não excesso."),
  q("Os céticos, como Pirro, propunham:", ["Suspender o juízo", "Confiar nos sentidos sempre", "Seguir a tradição", "Acreditar em tudo"], 0, "Diante de argumentos iguais para os dois lados, o cético suspende o juízo (epoché) e busca a tranquilidade."),
  q("Diógenes, o cínico, ficou famoso por:", ["Viver com o mínimo, contra convenções", "Governar Atenas por mais de vinte anos", "Escrever o diálogo A República", "Fundar o Liceu, a escola de Aristóteles"], 0, "Diógenes vivia num barril e zombava das convenções sociais, defendendo uma vida simples segundo a natureza."),
  q("O período helenístico começa após:", ["As conquistas de Alexandre", "A queda do Império Romano", "As Cruzadas ao Oriente Médio", "A Reforma de Martinho Lutero"], 0, "Com o império de Alexandre (século IV a.C.), a cultura grega se espalhou e a pólis perdeu autonomia."),
  q("A frase 'A morte não é nada para nós' é de:", ["Epicuro", "Platão", "Sócrates", "Tales"], 0, "Para Epicuro, quando a morte existe, nós não existimos; logo, não há o que temer."),
  qe("“Não são as coisas que nos perturbam, mas os juízos que fazemos sobre elas.” (Epicteto)", "Segundo o estoico, o sofrimento vem principalmente:", ["De como interpretamos os fatos", "Dos próprios acontecimentos em si", "Da vontade cruel dos deuses gregos", "Da falta de dinheiro e de bens"], 0, "Os fatos são neutros; nossos juízos sobre eles é que perturbam. Por isso o estoico trabalha a própria interpretação."),
  qe("“Não estragues o que tens desejando o que não tens.” (Epicuro)", "O conselho defende:", ["Moderação dos desejos", "Ambição sem limites", "Desprezo pelo prazer", "Inveja como motor"], 0, "Desejos excessivos trazem perturbação. Epicuro valoriza o simples: amizade, reflexão, necessidades naturais."),
  qe("Situação: antes de uma prova, um estudante pensa: 'Não controlo as questões que vão cair; controlo quanto estudei e como vou respirar agora'.", "A atitude do estudante se aproxima do:", ["Estoicismo", "Hedonismo de excessos", "Ceticismo radical", "Cinismo"], 0, "Separar o que depende de nós do que não depende é o núcleo da ética estoica (Epicteto, Marco Aurélio)."),
  qe("Marco Aurélio, imperador romano, escreveu em suas Meditações: “Você tem poder sobre sua mente, não sobre os acontecimentos.”", "O trecho mostra que o estoicismo:", ["Foi praticado até por imperadores", "Era proibido por lei em toda Roma", "Valorizava o luxo e a ostentação", "Negava qualquer valor à razão humana"], 0, "O estoicismo nasceu em Atenas (Zenão) e teve grandes nomes romanos: Sêneca, Epicteto (ex-escravo) e Marco Aurélio."),
  q("A escola estoica recebeu esse nome porque Zenão ensinava:", ["Num pórtico (stoa) de Atenas", "Num jardim fechado nos arredores", "Num templo egípcio de Alexandria", "Num navio que cruzava o Egeu"], 0, "Stoa = pórtico. Já Epicuro ensinava no 'Jardim'."),
  m("Marque os pares escola → ideia corretos:", ["Estoicismo: aceitar o que não depende de nós", "Epicurismo: prazer como ausência de dor", "Ceticismo: suspensão do juízo", "Cinismo: luxo e riqueza", "Estoicismo: busca de banquetes"], [0, 1, 2], "Cínicos pregavam vida simples e estoicos, controle das paixões."),
  m("Marque pensadores estoicos:", ["Sêneca", "Epicteto", "Marco Aurélio", "Epicuro", "Pirro"], [0, 1, 2], "Epicuro fundou o epicurismo; Pirro, o ceticismo."),
  o("Compare estoicismo e epicurismo quanto ao caminho para a felicidade.", "Ambos buscam a tranquilidade da alma. O estoicismo propõe viver segundo a razão, aceitando o que não depende de nós e controlando as paixões. O epicurismo propõe buscar prazeres moderados, entendidos como ausência de dor e de perturbação (ataraxia), valorizando a amizade e a vida simples.", [
    ["Estoicismo: razão e aceitar o que não depende de nós", "razao", "aceitar", "depende", "paixo"],
    ["Epicurismo: prazer moderado, ausência de dor", "prazer", "dor", "ataraxia", "moderad"],
    ["Ambos buscam tranquilidade", "tranquil", "serenidade", "paz"],
  ]),
], "n");

extend(FILOSOFIA, "Filosofia medieval", [
  q("O principal desafio da filosofia medieval foi:", ["Conciliar fé e razão", "Separar Estado e Igreja", "Explicar a evolução", "Criar a democracia"], 0, "Pensadores cristãos, muçulmanos e judeus tentaram mostrar que a razão filosófica e a revelação podiam concordar."),
  q("Santo Agostinho aproximou o cristianismo da filosofia de:", ["Platão", "Aristóteles", "Epicuro", "Demócrito"], 0, "Agostinho (séc. IV–V) leu Platão (via neoplatônicos): mundo das ideias aproximado da mente de Deus."),
  q("A Patrística é o período da filosofia cristã ligado:", ["Aos primeiros Padres da Igreja", "Às universidades do século XIII", "À Reforma Protestante", "Ao Iluminismo"], 0, "Patrística (séc. II–VIII): Padres da Igreja como Agostinho. A Escolástica (séc. IX–XIV) se desenvolveu nas escolas e universidades."),
  q("Para Agostinho, o mal é:", ["Uma substância criada por Deus", "Ausência do bem", "Uma ilusão dos sentidos", "Um deus rival"], 1, "O mal não é algo que Deus criou, mas falta de bem, que nasce do mau uso do livre-arbítrio."),
  q("As 'cinco vias' de Tomás de Aquino buscavam:", ["Provar pela razão que Deus existe", "Negar de vez a existência de Deus", "Explicar a origem do poder político", "Classificar animais e plantas do mundo"], 0, "Ex.: a via do primeiro motor: tudo que se move é movido por outro; deve haver um primeiro motor imóvel, Deus."),
  q("Na Idade Média, a filosofia era muitas vezes vista como 'serva' da:", ["Teologia", "Política", "Medicina", "Astronomia"], 0, "'Philosophia ancilla theologiae': a filosofia ajudaria a entender e defender as verdades da fé."),
  qe("“Creio para compreender e compreendo para crer.” (Santo Agostinho)", "A frase expressa que:", ["Fé e razão se ajudam", "A razão deve ser abandonada", "A fé não tem utilidade", "Só a ciência explica Deus"], 0, "Para Agostinho, a fé ilumina a razão e a razão aprofunda a fé: não são inimigas."),
  qe("Agostinho escreveu nas Confissões: “Tarde te amei, ó beleza tão antiga e tão nova!”", "O trecho tem caráter:", ["Autobiográfico e de conversão", "Científico e experimental", "Político e revolucionário", "Cético e materialista"], 0, "As Confissões narram a vida de Agostinho e sua conversão: é uma obra autobiográfica e espiritual."),
  qe("Tomás de Aquino, influenciado por Aristóteles, argumenta: “Tudo o que se move é movido por outro. É preciso chegar a um primeiro motor, que não é movido por nenhum outro.”", "O argumento pretende demonstrar:", ["A existência de Deus pela razão", "Que o universo é eterno sem causa", "Que o movimento não existe", "A teoria dos átomos"], 0, "É a primeira das cinco vias: o primeiro motor imóvel, que os cristãos chamam de Deus."),
  qe("Nas universidades medievais, os debates seguiam o método da 'disputatio': apresentar uma questão, argumentos contrários, a resposta e a refutação das objeções.", "Esse método é característico da:", ["Escolástica", "Patrística", "Filosofia pré-socrática", "Filosofia contemporânea"], 0, "A Escolástica ensinava por questões disputadas; a Suma Teológica de Tomás de Aquino segue esse formato."),
  q("Averróis e Avicena, pensadores do mundo islâmico, foram importantes por:", ["Comentar e preservar Aristóteles", "Destruir os textos gregos antigos", "Criar a imprensa na Europa medieval", "Fundar o protestantismo na Alemanha"], 0, "Filósofos árabes traduziram e comentaram Aristóteles, que voltou à Europa cristã por esses textos."),
  m("Marque os pares pensador → ideia corretos:", ["Agostinho: mal como ausência do bem", "Tomás de Aquino: cinco vias", "Agostinho: aproximação com Platão", "Tomás de Aquino: rejeitou Aristóteles", "Agostinho: viveu no Iluminismo"], [0, 1, 2], "Tomás se baseou em Aristóteles; Agostinho viveu nos séculos IV e V."),
  m("Marque características da Escolástica:", ["Ensino em escolas e universidades", "Método de questões disputadas", "Uso da lógica de Aristóteles", "Rejeição total da fé", "Defesa do ateísmo"], [0, 1, 2], "A Escolástica buscava harmonizar fé e razão, não rejeitar a fé."),
  o("Explique como Tomás de Aquino buscou conciliar fé e razão.", "Tomás de Aquino defendia que fé e razão não se contradizem, pois ambas vêm de Deus. Usou a filosofia de Aristóteles para demonstrar racionalmente verdades como a existência de Deus (as cinco vias). Algumas verdades, porém, só a revelação alcança, como a Trindade.", [
    ["Fé e razão não se contradizem", "nao se contradiz", "harmon", "concili", "complement"],
    ["Uso de Aristóteles", "aristoteles"],
    ["Cinco vias ou provas da existência de Deus", "cinco vias", "provar", "demonstr", "existencia de deus"],
  ]),
], "n");

extend(FILOSOFIA, "Racionalismo e empirismo", [
  q("Para o racionalismo, a principal fonte do conhecimento é:", ["A razão", "Os sentidos", "A tradição", "A revelação"], 0, "Racionalistas (Descartes, Spinoza, Leibniz) confiam na razão e em ideias inatas; empiristas, na experiência."),
  q("A dúvida metódica de Descartes consiste em:", ["Duvidar de tudo o que não é certo", "Negar que exista qualquer conhecimento", "Acreditar sempre no que os sentidos dizem", "Obedecer ao que a Igreja ensinava"], 0, "Descartes duvida de tudo que possa ser falso para achar uma certeza firme: 'penso, logo existo'."),
  q("'Tábula rasa' é a ideia de Locke de que a mente ao nascer:", ["Já traz ideias inatas guardadas", "É uma folha em branco", "Conhece Deus por intuição direta", "Sabe matemática sem aprender"], 1, "Para Locke, tudo o que sabemos vem da experiência (sensação e reflexão): não há ideias inatas."),
  q("David Hume questionou a ideia de causalidade porque:", ["Só vemos sucessão, não conexão", "Ela foi provada pela razão pura", "Os sentidos nunca nos enganam", "Deus garante todas as causas do mundo"], 0, "Vemos que o fogo vem antes do calor, mas a 'necessidade' é hábito da mente, não algo que se observa."),
  q("Francis Bacon defendia o método:", ["Indutivo e experimental", "Dedutivo sem experiência", "Da revelação", "Da dúvida absoluta"], 0, "Bacon propôs observar, experimentar e generalizar (indução), e criticou os 'ídolos' que distorcem o conhecimento."),
  q("Kant tentou superar o debate dizendo que o conhecimento:", ["Une experiência e formas da razão", "Vem só da razão, sem nenhuma experiência", "Vem só dos sentidos, sem nenhuma razão", "É impossível para qualquer ser humano"], 0, "Para Kant, 'pensamentos sem conteúdo são vazios; intuições sem conceitos são cegas': experiência e razão juntas."),
  qe("“Penso, logo existo.” (Descartes, Discurso do Método)", "Essa certeza resiste à dúvida porque:", ["Quem duvida pensa, e quem pensa existe", "Os sentidos confirmam que existimos", "A Igreja garante que ela é verdadeira", "Todos os filósofos concordam com ela"], 0, "Mesmo que tudo seja ilusão, quem duvida está pensando; logo, existe como ser pensante."),
  qe("“Nada há no intelecto que não tenha passado antes pelos sentidos.” (máxima adotada pelos empiristas)", "A frase está alinhada com:", ["O empirismo", "O racionalismo", "O ceticismo antigo", "A escolástica mística"], 0, "Afirma que todo conhecimento começa na experiência sensível, tese central de Locke e Hume."),
  qe("Situação: alguém vê o sol nascer todos os dias e conclui que ele nascerá amanhã. Hume diria que essa certeza vem:", "Segundo Hume, a crença no nascer do sol amanhã se baseia:", ["No hábito criado pela repetição", "Numa demonstração lógica e necessária", "Numa ideia inata em todas as mentes", "Numa revelação divina feita aos sábios"], 0, "A indução não é logicamente garantida: esperamos o futuro igual ao passado por costume (hábito)."),
  qe("Bacon falou dos 'ídolos da tribo', erros comuns a toda a espécie humana, como ver padrões onde não existem.", "Para Bacon, conhecer esses 'ídolos' ajuda a:", ["Evitar erros no conhecimento", "Adorar novos deuses na ciência", "Abandonar a ciência experimental", "Confiar mais nas aparências"], 0, "Os ídolos (da tribo, da caverna, do foro, do teatro) são preconceitos; reconhecê-los torna a investigação mais confiável."),
  q("O 'gênio maligno' de Descartes é:", ["Hipótese para radicalizar a dúvida", "Um personagem real da história francesa", "Um demônio adorado pelos medievais", "Uma prova direta de que Deus existe"], 0, "Descartes imagina um enganador poderoso para testar até a matemática; só o 'penso, logo existo' resiste."),
  m("Marque os racionalistas:", ["Descartes", "Spinoza", "Leibniz", "Locke", "Hume"], [0, 1, 2], "Locke e Hume são empiristas."),
  m("Marque teses empiristas:", ["A mente nasce como tábula rasa", "O conhecimento vem da experiência", "A causalidade vem do hábito", "Há ideias inatas", "Só a razão pura conhece"], [0, 1, 2], "Ideias inatas e razão pura são teses racionalistas."),
  o("Explique a diferença entre racionalismo e empirismo.", "O racionalismo afirma que a razão é a principal fonte do conhecimento e que existem ideias inatas, como em Descartes. O empirismo afirma que o conhecimento vem da experiência sensível e que a mente nasce como tábula rasa, como em Locke e Hume.", [
    ["Racionalismo: razão e ideias inatas", "razao", "inata"],
    ["Empirismo: experiência e sentidos", "experienc", "sentidos", "tabula rasa"],
    ["Cita um autor de cada", "descartes", "locke", "hume", "leibniz", "spinoza", "bacon"],
  ]),
], "n");

extend(FILOSOFIA, "Iluminismo e Kant", [
  q("O Iluminismo (século XVIII) defendia, acima de tudo:", ["O uso da razão contra a superstição", "A volta ao poder absoluto dos reis", "A submissão total à Igreja", "O abandono da ciência moderna"], 0, "As 'Luzes' confiavam na razão para criticar o absolutismo, os privilégios e a superstição."),
  q("O imperativo categórico de Kant manda agir:", ["Como se a regra valesse para todos", "Sempre buscando o próprio prazer", "Conforme o que der mais lucro", "Do jeito que a maioria aprovar"], 0, "'Age só segundo a máxima que possas querer como lei universal': a ação moral vale para qualquer um."),
  q("Para Kant, uma ação tem valor moral quando é feita:", ["Por dever", "Por medo", "Por interesse", "Por hábito"], 0, "Ajudar alguém só para ganhar fama não tem valor moral; o valor está em agir por respeito ao dever."),
  q("Kant diz que devemos tratar as pessoas sempre como:", ["Fins em si mesmas", "Meios para nossos fins", "Peças de um sistema", "Inferiores ao Estado"], 0, "Fórmula da humanidade: nunca usar alguém apenas como meio, pois toda pessoa tem dignidade."),
  q("A Enciclopédia, de Diderot e D'Alembert, buscava:", ["Reunir e divulgar o saber da época", "Proibir livros científicos na França", "Defender o direito divino dos reis", "Registrar só textos religiosos"], 0, "A Enciclopédia reuniu conhecimentos de ciência, técnica e filosofia, espalhando as ideias iluministas."),
  q("Voltaire ficou conhecido pela defesa da:", ["Tolerância religiosa", "Inquisição católica", "Censura prévia de livros", "Escravidão nas colônias"], 0, "Voltaire criticou o fanatismo e a intolerância religiosa e defendeu a liberdade de expressão."),
  qe("“Esclarecimento é a saída do homem de sua menoridade, da qual ele próprio é culpado. Menoridade é a incapacidade de usar o próprio entendimento sem a direção de outro.” (Kant)", "Para Kant, a menoridade é superada quando a pessoa:", ["Passa a pensar por conta própria", "Obedece sempre às autoridades", "Completa 18 anos de idade", "Decora o que os livros dizem"], 0, "Menoridade não é idade: é depender do pensamento alheio por preguiça ou covardia. 'Sapere aude!'"),
  qe("Situação: um aluno pensa em colar na prova e pergunta a si mesmo: 'E se todos colassem?'. Conclui que, assim, as provas perderiam o sentido.", "O raciocínio do aluno aplica:", ["O imperativo categórico", "O utilitarismo de Bentham e Mill", "O hedonismo moderado de Epicuro", "O ceticismo radical de Pirro"], 0, "Ele testa se a regra ('colar') pode valer para todos. Como não pode sem se destruir, a ação não é moral para Kant."),
  qe("“Posso não concordar com uma palavra do que dizes, mas defenderei até a morte o teu direito de dizê-lo.” (frase associada a Voltaire)", "A frase defende:", ["A liberdade de expressão", "A censura das opiniões contrárias", "A obediência absoluta ao rei", "O fim dos debates públicos"], 0, "Mesmo discordando, defende-se o direito do outro de falar: base da tolerância iluminista."),
  qe("Kant distinguiu o imperativo hipotético ('Se quer passar, estude') do categórico ('Não minta').", "O imperativo categórico é diferente porque:", ["Vale sem depender de um objetivo", "Só vale para quem quer passar", "É um conselho de saúde", "Depende do resultado da ação"], 0, "O hipotético depende de um fim desejado; o categórico obriga incondicionalmente, como dever moral."),
  q("Para Kant, a mentira é errada mesmo para salvar alguém porque:", ["Não pode virar regra universal", "Sempre dá prejuízo financeiro", "A lei do país a proíbe", "Os outros podem descobrir"], 0, "Se todos mentissem quando conviesse, ninguém acreditaria em ninguém: a máxima se autodestrói."),
  m("Marque ideias de Kant:", ["Imperativo categórico", "Agir por dever", "Pessoas como fins em si", "O homem é lobo do homem", "Mais-valia"], [0, 1, 2], "'Lobo do homem' é Hobbes; mais-valia é Marx."),
  m("Marque ideias iluministas:", ["Razão contra a superstição", "Tolerância religiosa", "Divisão dos poderes", "Direito divino dos reis", "Fim da ciência"], [0, 1, 2], "O direito divino dos reis era justamente o que os iluministas criticavam."),
  o("Explique o imperativo categórico de Kant e dê um exemplo.", "O imperativo categórico é uma regra moral que vale para todos, sem depender de interesses: devo agir só segundo uma máxima que eu possa querer como lei universal. Ex.: não posso mentir para conseguir algo, pois se todos mentissem ninguém confiaria em promessas.", [
    ["Regra que vale para todos (universal)", "universal", "todos", "lei"],
    ["Não depende de interesses ou resultados", "interess", "incondicion", "dever", "nao depende"],
    ["Exemplo coerente", "mentir", "mentira", "promessa", "colar", "exemplo"],
  ]),
], "n");

extend(FILOSOFIA, "Ética", [
  q("Ética e moral costumam ser diferenciadas assim:", ["Ética reflete sobre a moral", "As duas são a mesma lei", "Moral é só a lei escrita", "Ética trata só de negócios"], 0, "Moral são os valores e costumes de um grupo; ética é a reflexão filosófica sobre esses valores."),
  q("O utilitarismo (Bentham, Mill) julga uma ação pelo:", ["Bem-estar que ela produz", "Respeito à tradição dos antigos", "Dever em si mesmo, sem olhar efeitos", "Mandamento religioso que a orienta"], 0, "Certo é o que gera a maior felicidade para o maior número de pessoas: importam as consequências."),
  q("Relativismo moral é a ideia de que:", ["Os valores variam com a cultura", "Existe uma moral única, fixa e eterna", "Não existe nenhuma cultura humana", "Só a ciência pode definir o que é o bem"], 0, "O relativismo afirma que certo e errado dependem do contexto cultural. Críticos apontam o risco de aceitar qualquer prática."),
  q("Autonomia moral significa:", ["Dar a si mesmo a regra pela razão", "Obedecer cegamente aos outros", "Agir sem pensar nas pessoas", "Seguir apenas o que a lei manda"], 0, "Autonomia (auto = si; nomos = lei): a pessoa segue regras que sua razão reconhece. Heteronomia é seguir regras impostas."),
  q("A ética do cuidado valoriza principalmente:", ["As relações e a atenção ao outro", "O cálculo de lucro das ações", "A obediência às hierarquias", "A competição entre pessoas"], 0, "Pensadoras como Carol Gilligan destacam vínculos, empatia e responsabilidade pelo outro concreto."),
  q("Bioética é o campo que discute:", ["Questões morais da vida e da saúde", "Regras de competições esportivas", "O cálculo de impostos do país", "A gramática da língua portuguesa"], 0, "Bioética trata de temas como eutanásia, transgênicos, experimentos com humanos e clonagem."),
  qe("Dilema do bonde: um bonde vai atropelar cinco pessoas. Você pode puxar uma alavanca e desviá-lo para um trilho onde ele atingirá uma pessoa.", "Um utilitarista tenderia a:", ["Desviar o bonde e salvar mais vidas", "Não agir, para não carregar culpa alguma", "Sortear quem deve morrer nos trilhos", "Esperar que alguém decida no seu lugar"], 0, "O utilitarista olha as consequências: uma morte é menos ruim que cinco. Críticos dizem que usar alguém como meio é errado (Kant)."),
  qe("“A ética não é uma teoria guardada no livro; é o modo como tratamos as pessoas quando ninguém está olhando.”", "O texto defende que a ética se mostra principalmente:", ["Nas atitudes do dia a dia", "Em provas escritas", "Apenas nas leis do país", "Só em discursos públicos"], 0, "A ética se realiza na prática, inclusive quando não há vigilância nem punição."),
  qe("Situação: uma empresa descobre que seu produto pode causar alergia rara. Divulgar o problema reduz o lucro; esconder protege as vendas.", "Do ponto de vista ético, a empresa deveria:", ["Informar os consumidores do risco", "Esconder até que alguém processe", "Aumentar o preço do produto", "Culpar os consumidores alérgicos"], 0, "A ética exige considerar os afetados: omitir um risco à saúde viola a dignidade e a confiança do consumidor."),
  qe("Para Aristóteles, a pessoa prudente (phronesis) é a que sabe agir bem em cada situação concreta.", "A prudência, nesse sentido, é:", ["Saber aplicar o bem ao caso real", "Medo de agir em qualquer caso", "Decorar regras sem entendê-las", "Agir sempre do mesmo jeito"], 0, "A phronesis é a sabedoria prática: perceber o que a situação pede e escolher o justo meio."),
  q("Para Kant, mentir para obter vantagem é errado porque:", ["Trata o outro só como meio", "Pode trazer mais dinheiro", "Toda lei proíbe mentir", "É difícil lembrar a mentira"], 0, "Mentir para lucrar usa a pessoa como instrumento, sem respeitar sua dignidade."),
  m("Marque os pares teoria → critério corretos:", ["Utilitarismo: consequências", "Kant: dever", "Aristóteles: virtude", "Utilitarismo: tradição", "Kant: prazer"], [0, 1, 2], "O utilitarismo olha consequências e Kant rejeita o prazer como critério moral."),
  m("Marque temas da bioética:", ["Eutanásia", "Pesquisa com células-tronco", "Doação de órgãos", "Câmbio do dólar", "Regras do futebol"], [0, 1, 2], "Câmbio e futebol não são temas de bioética."),
  o("Diferencie ética de moral.", "Moral é o conjunto de valores, normas e costumes que orientam a conduta de um grupo numa época. Ética é a reflexão filosófica sobre esses valores: pergunta por que algo é certo ou errado e se as normas são justas.", [
    ["Moral = valores e costumes de um grupo", "costume", "norma", "valores", "grupo"],
    ["Ética = reflexão sobre a moral", "reflex", "pensar", "questiona", "por que"],
    ["A moral varia com tempo ou cultura", "epoca", "cultura", "tempo", "sociedade"],
  ]),
], "n");

extend(FILOSOFIA, "Contratualistas", [
  q("Os contratualistas explicam a origem do Estado por:", ["Um acordo entre as pessoas", "Uma ordem direta de Deus", "A força natural dos reis", "O acaso da história"], 0, "Hobbes, Locke e Rousseau imaginam um estado de natureza e um pacto que funda a sociedade política."),
  q("Para Locke, se o governo viola os direitos naturais, o povo:", ["Pode resistir e trocá-lo", "Deve obedecer sempre", "Perde todos os direitos", "Volta a viver isolado"], 0, "O direito de resistência é central em Locke e inspirou a Revolução Gloriosa e a independência dos EUA."),
  q("A 'vontade geral' de Rousseau é:", ["O interesse comum do povo", "A soma das vontades egoístas", "O desejo do governante", "A opinião dos mais ricos"], 0, "A vontade geral visa o bem comum, não a soma dos interesses particulares (a 'vontade de todos')."),
  q("Para Hobbes, a melhor forma de garantir a paz é:", ["Um soberano com poder forte", "A ausência de qualquer governo", "A divisão total do poder", "O fim da propriedade"], 0, "No Leviatã, os indivíduos entregam ao soberano o poder de garantir a segurança e evitar a guerra."),
  q("Para Rousseau, a origem da desigualdade está ligada:", ["À propriedade privada", "À natureza humana má", "Ao clima de cada país", "À vontade dos deuses"], 0, "'O primeiro que cercou um terreno e disse isto é meu' fundou a sociedade civil e a desigualdade."),
  q("No estado de natureza de Locke, as pessoas já possuíam:", ["Direitos naturais", "Um rei com poder absoluto", "Leis escritas e tribunais", "Uma moeda única para trocas"], 0, "Para Locke, mesmo antes do Estado havia direitos à vida, à liberdade e à propriedade, que o governo deve proteger."),
  qe("“Durante o tempo em que os homens vivem sem um poder comum capaz de mantê-los em respeito, eles se encontram na condição de guerra de todos contra todos.” (Hobbes)", "Para Hobbes, sem um poder comum, a vida humana seria:", ["Insegura e violenta", "Pacífica e feliz", "Igual à de hoje", "Guiada pela bondade"], 0, "Hobbes descreve a vida no estado de natureza como 'solitária, pobre, sórdida, brutal e curta'."),
  qe("“O homem nasce livre, e por toda parte encontra-se a ferros.” (Rousseau, O Contrato Social)", "A frase critica:", ["Sociedades que tiram a liberdade", "A liberdade natural de cada pessoa", "A educação dada às crianças pobres", "O estudo da filosofia nas escolas"], 0, "Rousseau denuncia instituições injustas que acorrentam o homem; o contrato social legítimo deve devolver a liberdade."),
  qe("Declaração de Independência dos EUA (1776): “Todos os homens são criados iguais, dotados de direitos inalienáveis, entre os quais a vida, a liberdade e a busca da felicidade.”", "O trecho tem forte influência de:", ["John Locke", "Thomas Hobbes", "Nicolau Maquiavel", "Santo Agostinho"], 0, "A ideia de direitos naturais inalienáveis (vida, liberdade, propriedade/felicidade) vem de Locke."),
  qe("Situação: numa ilha sem leis, náufragos decidem criar regras e escolher alguém para fazê-las cumprir, em troca de abrir mão de parte da liberdade.", "A situação ilustra a ideia de:", ["Contrato social", "Direito divino", "Luta de classes", "Mito da caverna"], 0, "Abrir mão de parte da liberdade em troca de segurança e ordem é o núcleo do contratualismo."),
  q("Para Rousseau, a soberania pertence:", ["Ao povo", "Ao rei", "À Igreja", "Ao exército"], 0, "A soberania popular é inalienável: o povo é a fonte do poder legítimo."),
  m("Marque os pares contratualista → ideia corretos:", ["Hobbes: guerra de todos contra todos", "Locke: direitos naturais", "Rousseau: vontade geral", "Locke: soberano absoluto", "Hobbes: bom selvagem"], [0, 1, 2], "Soberano absoluto é Hobbes; 'bom selvagem' é associado a Rousseau."),
  m("Marque o que Locke considerava direitos naturais:", ["Vida", "Liberdade", "Propriedade", "Privilégios da nobreza", "Obediência ao rei"], [0, 1, 2], "Privilégios e obediência absoluta eram justamente o que o liberalismo de Locke combatia."),
  o("Compare a visão de Hobbes e de Rousseau sobre o ser humano no estado de natureza.", "Para Hobbes, no estado de natureza o ser humano vive em guerra de todos contra todos: é movido pelo medo e pelo interesse, por isso precisa de um Estado forte. Para Rousseau, o ser humano nasce bom e livre; é a sociedade, com a propriedade privada, que o corrompe e gera desigualdade.", [
    ["Hobbes: guerra de todos contra todos", "guerra", "medo", "lobo"],
    ["Hobbes: precisa de Estado forte", "estado forte", "soberano", "leviata"],
    ["Rousseau: nasce bom; a sociedade corrompe", "bom", "corromp", "propriedade"],
  ]),
], "n");

extend(FILOSOFIA, "Marx e Nietzsche", [
  q("Para Marx, a infraestrutura de uma sociedade é:", ["A base econômica e de produção", "O conjunto de ideias e leis", "A religião oficial do país", "O sistema de transportes"], 0, "A infraestrutura (forças e relações de produção) condiciona a superestrutura (leis, política, religião, ideias)."),
  q("Mais-valia, para Marx, é:", ["Valor produzido e não pago ao trabalhador", "O aumento natural dos salários com o tempo", "O lucro honesto obtido no comércio livre", "O imposto que as empresas pagam ao governo"], 0, "O trabalhador produz mais valor do que recebe em salário; a diferença é apropriada pelo capitalista."),
  q("Alienação do trabalho, em Marx, ocorre quando o trabalhador:", ["Não se reconhece no que produz", "Ganha um salário muito alto", "Escolhe seu próprio horário", "Trabalha em cooperativa"], 0, "Separado do produto e do processo, o trabalhador vira peça da máquina e se torna estranho ao próprio trabalho."),
  q("Nietzsche anunciou a 'morte de Deus' para dizer que:", ["Os valores cristãos perderam força", "Deus foi assassinado de fato por alguém", "A religião nunca existiu na história", "A ciência moderna chegou ao seu fim"], 0, "É um diagnóstico cultural: a crença que sustentava os valores ocidentais ruiu, abrindo espaço ao niilismo."),
  q("O 'além-do-homem' (Übermensch) de Nietzsche é quem:", ["Cria os próprios valores", "Obedece à moral de rebanho", "Busca a vida após a morte", "Renuncia a toda vontade"], 0, "É o ser que supera o niilismo afirmando a vida e criando novos valores."),
  q("Para Nietzsche, a 'moral de rebanho' é a moral que:", ["Valoriza obediência e igualdade", "Exalta a criação individual de valores", "Nasce da força dos mais poderosos", "Rejeita todo e qualquer costume social"], 0, "Nietzsche critica a moral que, por ressentimento, transforma fraqueza em virtude e nivela todos."),
  qe("“Os filósofos apenas interpretaram o mundo de diferentes maneiras; o que importa é transformá-lo.” (Marx, Teses sobre Feuerbach)", "A frase defende que a filosofia deve:", ["Agir para mudar a realidade", "Limitar-se a contemplar o mundo", "Abandonar a política", "Defender a ordem existente"], 0, "Marx propõe a práxis: unir teoria e ação para transformar a sociedade."),
  qe("“As ideias da classe dominante são, em cada época, as ideias dominantes.” (Marx e Engels, A Ideologia Alemã)", "Segundo o trecho, as ideias que predominam numa sociedade:", ["Servem a quem domina", "São neutras e iguais para todas as classes", "Surgem por acaso, sem relação com nada", "Vêm sempre dos grupos mais pobres"], 0, "Quem controla os meios de produção também controla a produção de ideias (ideologia)."),
  qe("“Torna-te quem tu és.” (Nietzsche)", "A frase incentiva o indivíduo a:", ["Afirmar a si mesmo", "Imitar os outros em tudo o que fazem", "Seguir a tradição sem questionar", "Fugir de si mesmo e de sua história"], 0, "Para Nietzsche, cada um deve afirmar sua singularidade e criar seu caminho, contra a moral de rebanho."),
  qe("Situação: um operário passa o dia apertando o mesmo parafuso numa linha de montagem e nunca vê o carro pronto.", "A situação ilustra o conceito marxista de:", ["Alienação", "Mais-valia absoluta", "Vontade geral", "Imperativo categórico"], 0, "O operário não se reconhece no produto final nem controla o processo: está alienado do próprio trabalho."),
  q("Para Marx, o motor da história é:", ["A luta de classes", "A vontade dos heróis", "O progresso das artes", "O acaso"], 0, "Conflitos entre classes (senhores × escravos, burgueses × proletários) movem as transformações sociais."),
  m("Marque conceitos de Marx:", ["Mais-valia", "Alienação", "Luta de classes", "Além-do-homem", "Vontade de potência"], [0, 1, 2], "Além-do-homem e vontade de potência são de Nietzsche."),
  m("Marque ideias de Nietzsche:", ["Morte de Deus", "Vontade de potência", "Crítica à moral de rebanho", "Ditadura do proletariado", "Contrato social"], [0, 1, 2], "Ditadura do proletariado é Marx; contrato social, contratualistas."),
  o("Explique o conceito de mais-valia em Marx.", "Mais-valia é a diferença entre o valor que o trabalhador produz e o salário que recebe. O trabalhador trabalha mais horas do que o necessário para pagar seu salário; o valor excedente fica com o capitalista e é a fonte do lucro e da exploração.", [
    ["Diferença entre o valor produzido e o salário", "diferenca", "salario", "valor"],
    ["O excedente fica com o capitalista", "capitalista", "patrao", "dono", "lucro"],
    ["Base da exploração", "explora"],
  ]),
], "n");

extend(FILOSOFIA, "Existencialismo", [
  q("Para Sartre, estar 'condenado a ser livre' significa que:", ["Não podemos deixar de escolher", "A liberdade é uma punição legal", "Somos escravos do destino", "Só os ricos são livres"], 0, "Mesmo não escolher é uma escolha: somos responsáveis pelo que fazemos de nós."),
  q("A 'má-fé', para Sartre, é:", ["Fugir da própria liberdade", "Enganar outras pessoas para ganhar dinheiro", "Não seguir nenhuma religião ao longo da vida", "Quebrar uma promessa feita a um amigo"], 0, "É fingir que não temos escolha ('eu tinha que fazer'), culpando o destino, a natureza ou os outros."),
  q("Simone de Beauvoir escreveu 'Ninguém nasce mulher: torna-se mulher' para mostrar que:", ["O ser mulher é construído", "A biologia define tudo o que a mulher é", "As mulheres não têm nenhuma escolha", "O gênero não existe em nenhuma cultura"], 0, "Em O Segundo Sexo, Beauvoir mostra que os papéis femininos são construídos pela cultura, não destino biológico."),
  q("Para Camus, o 'absurdo' nasce do choque entre:", ["Busca de sentido e mundo mudo", "A ciência moderna e a religião antiga", "O corpo mortal e a alma imortal", "O Estado autoritário e o indivíduo livre"], 0, "Queremos sentido; o mundo não responde. Camus propõe revoltar-se e viver com intensidade mesmo assim."),
  q("No Mito de Sísifo, Camus conclui que:", ["Devemos imaginar Sísifo feliz", "Sísifo deve desistir de rolar a pedra", "Os deuses gregos são justos com Sísifo", "Todo trabalho humano é inútil e vazio"], 0, "Mesmo rolando a pedra para sempre, Sísifo pode assumir sua condição com lucidez: a revolta dá sentido."),
  q("Kierkegaard é considerado precursor do existencialismo porque valorizou:", ["A angústia da escolha", "A lógica formal e os silogismos", "A economia política e o mercado", "Os números e a harmonia do cosmos"], 0, "Kierkegaard destacou o indivíduo diante de escolhas e a angústia da liberdade."),
  qe("“O homem nada mais é do que aquilo que ele faz de si mesmo.” (Sartre)", "A frase expressa a ideia de que:", ["Somos definidos por nossas escolhas", "Nascemos com uma essência pronta", "O destino decide por nós", "A sociedade nos define sozinha"], 0, "Não há natureza humana prévia: cada um se constrói por seus atos e responde por eles."),
  qe("“O inferno são os outros.” (Sartre, Entre Quatro Paredes)", "A frase sugere que:", ["O olhar alheio pesa sobre nós", "Devemos viver isolados de todos", "Os outros são maus por natureza", "O inferno é um lugar físico real"], 0, "Na peça, os personagens se aprisionam no julgamento uns dos outros: dependemos do olhar alheio."),
  qe("Situação: um jovem diz 'Fiz o curso que meus pais queriam, não tive escolha'. Um existencialista responderia:", "Para Sartre, a atitude do jovem é:", ["Má-fé, pois ele escolheu obedecer", "Correta, pois não havia escolha", "Coragem diante da liberdade", "Sinal de autenticidade"], 0, "Obedecer também foi uma escolha. Negar isso para fugir da responsabilidade é má-fé."),
  qe("“Angústia é a vertigem da liberdade.” (Kierkegaard)", "Para o filósofo, a angústia surge:", ["Diante das possibilidades", "Da falta de dinheiro para viver", "Do medo de animais selvagens", "Das doenças que atingem o corpo"], 0, "A angústia vem de sermos livres: o abismo das possibilidades e a responsabilidade de escolher."),
  q("O existencialismo se resume na tese de que:", ["A existência precede a essência", "A essência precede a existência", "Tudo é determinado", "A razão é inata"], 0, "Primeiro existimos, depois nos definimos. Para um objeto (um martelo), a essência (função) vem antes."),
  m("Marque pensadores ligados ao existencialismo:", ["Sartre", "Simone de Beauvoir", "Camus", "Tomás de Aquino", "Bacon"], [0, 1, 2], "Tomás de Aquino é medieval; Bacon, empirista moderno."),
  m("Marque conceitos existencialistas:", ["Angústia", "Má-fé", "Absurdo", "Mais-valia", "Silogismo"], [0, 1, 2], "Mais-valia é Marx; silogismo, Aristóteles."),
  o("Explique a frase de Sartre 'a existência precede a essência'.", "Significa que o ser humano primeiro existe e só depois se define por suas escolhas e ações. Não há uma natureza humana pronta nem um destino: somos livres e responsáveis por aquilo que fazemos de nós mesmos.", [
    ["Primeiro existimos, depois nos definimos", "primeiro exist", "depois", "define"],
    ["Não há natureza humana pronta", "natureza", "pronta", "destino", "essencia"],
    ["Liberdade e responsabilidade pelas escolhas", "livre", "liberdade", "responsa", "escolh"],
  ]),
], "n");

extend(FILOSOFIA, "Filosofia contemporânea", [
  q("Para Hannah Arendt, a 'banalidade do mal' mostra que:", ["Gente comum faz o mal sem pensar", "O mal é sempre monstruoso e muito raro", "Só pessoas loucas cometem grandes crimes", "O mal não existe de verdade no mundo"], 0, "Ao acompanhar o julgamento de Eichmann, Arendt viu um burocrata obediente que não pensava no que fazia."),
  q("Michel Foucault estudou como o poder:", ["Disciplina corpos em instituições", "Pertence apenas ao rei e à sua corte", "Desapareceu de vez na era moderna", "Existe somente nas leis escritas do país"], 0, "Para Foucault, o poder circula em instituições e práticas que vigiam, normalizam e disciplinam."),
  q("O 'véu da ignorância' de John Rawls serve para:", ["Escolher regras justas e imparciais", "Esconder informações importantes do povo", "Proibir o voto de quem não estudou", "Defender os privilégios de quem já tem"], 0, "Sem saber nossa posição social, escolheríamos regras justas para todos, protegendo os menos favorecidos."),
  q("Para Karl Popper, uma teoria é científica se:", ["Puder ser testada e refutada", "For aceita pela maioria", "Nunca puder ser contestada", "Vier de um cientista famoso"], 0, "Falseabilidade: a ciência faz previsões que poderiam dar errado. Teorias que explicam tudo não são científicas."),
  q("Thomas Kuhn chamou de 'revolução científica' a:", ["Troca de um paradigma por outro", "Descoberta de um fato isolado", "Fundação de uma universidade", "Proibição de teorias"], 0, "Quando anomalias se acumulam, a ciência troca de paradigma, como do geocentrismo para o heliocentrismo."),
  q("A Escola de Frankfurt criticou a razão instrumental, que é a razão usada:", ["Só para calcular meios eficazes", "Para refletir sobre fins justos e bons", "Na criação da arte e da poesia", "Na meditação e na oração religiosa"], 0, "A razão instrumental pergunta 'como fazer' e não 'para quê': pode servir à dominação, segundo Adorno e Horkheimer."),
  qe("“O pior mal não é cometido por pessoas cruéis, mas por pessoas que não pensam no que fazem.” (ideia inspirada em Hannah Arendt)", "A ideia destaca a importância de:", ["Pensar antes de obedecer", "Obedecer sem fazer nenhuma pergunta", "Punir apenas as pessoas cruéis", "Evitar qualquer envolvimento político"], 0, "Para Arendt, a ausência de pensamento (irreflexão) permite que gente comum participe de grandes crimes."),
  qe("O panóptico é uma prisão circular em que o vigia, numa torre central, pode ver todos sem ser visto. Os presos passam a se comportar como se fossem sempre observados.", "Foucault usou o panóptico para explicar:", ["Vigilância que gera autodisciplina", "A arquitetura gótica das igrejas medievais", "A liberdade total dos presos na cadeia", "O fim das prisões na sociedade moderna"], 0, "Saber-se observado faz o indivíduo se vigiar: modelo do poder disciplinar moderno (e das câmeras e redes de hoje)."),
  qe("Rawls propõe que as desigualdades só são justas se beneficiarem os menos favorecidos.", "Segundo esse princípio, uma política seria justa se:", ["Melhorasse a vida dos mais pobres", "Aumentasse só os lucros dos ricos", "Mantivesse tudo igual", "Eliminasse todos os direitos"], 0, "É o 'princípio da diferença': desigualdade aceitável é a que ajuda quem está em pior situação."),
  qe("Situação: uma teoria afirma que tudo o que acontece confirma suas ideias, mesmo fatos opostos.", "Para Popper, essa teoria:", ["Não é científica", "É a mais científica de todas as teorias", "Foi comprovada para sempre pelos fatos", "Deve ser ensinada como lei universal"], 0, "Se nada pode contradizê-la, ela não arrisca previsões: falta falseabilidade."),
  q("Habermas defende que normas legítimas surgem:", ["Do diálogo entre os envolvidos", "Da ordem dada por um líder forte", "Do funcionamento livre do mercado", "Da tradição aceita sem nenhum debate"], 0, "Ação comunicativa: acordos alcançados por argumentos, com todos podendo participar em igualdade."),
  m("Marque os pares pensador → ideia corretos:", ["Arendt: banalidade do mal", "Foucault: poder disciplinar", "Rawls: véu da ignorância", "Popper: mais-valia", "Kuhn: imperativo categórico"], [0, 1, 2], "Mais-valia é Marx; imperativo categórico, Kant. Popper fala de falseabilidade; Kuhn, de paradigmas."),
  m("Marque temas da filosofia contemporânea:", ["Poder e vigilância", "Justiça social", "Limites da ciência", "Busca da arché", "Cinco vias de Deus"], [0, 1, 2], "A arché é pré-socrática; as cinco vias, medievais."),
  o("Explique o conceito de 'banalidade do mal', de Hannah Arendt.", "Ao observar o julgamento de Eichmann, oficial nazista, Arendt percebeu que ele não era um monstro, mas um funcionário comum que obedecia ordens sem pensar. A banalidade do mal mostra que grandes crimes podem ser cometidos por pessoas que deixam de refletir sobre o que fazem.", [
    ["Caso Eichmann / nazismo", "eichmann", "nazis"],
    ["Pessoa comum, não monstro", "comum", "monstro", "funcionari", "burocrat"],
    ["Falta de reflexão / obediência", "pensar", "reflet", "reflexao", "obedec"],
  ]),
], "n");

extend(FILOSOFIA, "Filosofia política", [
  q("Para Maquiavel, a 'virtù' do governante é:", ["Saber agir conforme a ocasião", "A bondade cristã sem nenhuma exceção", "A riqueza herdada da própria família", "A obediência total às ordens do papa"], 0, "Virtù é a capacidade de ler a situação e agir com astúcia para conservar o poder; a fortuna é o acaso."),
  q("Democracia direta é aquela em que:", ["Os cidadãos decidem eles mesmos", "Representantes decidem por todos", "Um rei decide sozinho", "Os sábios governam"], 0, "Na democracia direta (como em Atenas) os cidadãos votam as leis; na representativa, elegem quem decide."),
  q("O liberalismo político defende principalmente:", ["Direitos individuais e Estado limitado", "O fim da propriedade privada dos meios", "Um rei colocado acima de todas as leis", "O fim das eleições e dos parlamentos"], 0, "O liberalismo (Locke, Montesquieu) protege liberdades individuais e limita o poder estatal."),
  q("Para Max Weber, o Estado tem o monopólio:", ["Do uso legítimo da força", "Da produção de alimentos", "Da educação religiosa", "Do comércio exterior"], 0, "Só o Estado pode usar a força de modo legítimo dentro de um território (polícia, Justiça)."),
  q("A separação dos poderes serve para:", ["Evitar abusos de um poder", "Fortalecer só o Poder Executivo", "Acabar de vez com o Judiciário", "Dar todo o poder ao rei ou presidente"], 0, "Executivo, Legislativo e Judiciário se fiscalizam ('freios e contrapesos'), como propôs Montesquieu."),
  q("Anarquismo é a corrente política que defende:", ["Uma sociedade sem Estado", "Um Estado que controla tudo", "A monarquia absoluta hereditária", "O governo exclusivo dos ricos"], 0, "Anarquistas (como Bakunin e Proudhon) propõem organização social sem Estado e sem hierarquias impostas."),
  qe("“Quem quer que pense fundar um Estado deve supor que todos os homens são maus.” (Maquiavel)", "Para Maquiavel, o governante deve:", ["Ser realista sobre a natureza humana", "Confiar na bondade de todos", "Ignorar os riscos da política", "Seguir apenas a moral religiosa"], 0, "Maquiavel separa política e moral: o governante deve agir com realismo para manter o Estado."),
  qe("Constituição brasileira, art. 1º, parágrafo único: “Todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente.”", "O trecho estabelece:", ["A soberania popular", "O poder absoluto do presidente", "O direito divino dos governantes", "O voto apenas dos ricos"], 0, "O poder vem do povo (soberania popular), exercido por representantes ou diretamente (plebiscito, referendo)."),
  qe("“O poder corrompe; o poder absoluto corrompe absolutamente.” (Lord Acton)", "A frase justifica:", ["Limitar e controlar o poder", "Dar mais poder a uma só pessoa", "Abolir todas as leis do país", "Fazer eleições sem nenhuma regra"], 0, "Se o poder tende a corromper, é preciso dividi-lo e fiscalizá-lo: base da separação dos poderes."),
  qe("Situação: um governo decide sozinho sem consultar ninguém, censura jornais e prende opositores.", "Esse governo é característico de um regime:", ["Autoritário", "Democrático", "Liberal", "Anarquista"], 0, "Concentração de poder, censura e perseguição a opositores são marcas de regimes autoritários."),
  q("Plebiscito e referendo são instrumentos de:", ["Participação direta", "Censura de jornais e livros", "Fortalecimento da monarquia", "Ditadura de um partido só"], 0, "O povo vota diretamente sobre uma questão: o plebiscito antes da lei; o referendo depois, para confirmar ou rejeitar."),
  m("Marque ideias de Maquiavel:", ["Virtù e fortuna", "Separar política e moral religiosa", "Mais vale ser temido que amado, se preciso", "Vontade geral", "Tábula rasa"], [0, 1, 2], "Vontade geral é Rousseau; tábula rasa, Locke."),
  m("Marque mecanismos democráticos:", ["Eleições livres", "Separação dos poderes", "Liberdade de imprensa", "Censura prévia", "Partido único"], [0, 1, 2], "Censura e partido único são marcas de regimes autoritários."),
  o("Explique por que Maquiavel é considerado o fundador da ciência política moderna.", "Porque analisou a política como ela é, e não como deveria ser. Em O Príncipe, separou a política da moral religiosa e mostrou que o governante precisa de virtù (habilidade) para lidar com a fortuna (acaso) e manter o poder e o Estado.", [
    ["Política como ela é (realismo)", "como ela e", "real", "realis"],
    ["Separou política e moral religiosa", "moral", "separ", "religi"],
    ["Virtù e fortuna / manter o poder", "virtu", "fortuna", "poder"],
  ]),
], "n");
